  "A Boards page": "Isang page ng Mga board",
  "A board is a note with lanes of cards: drag cards from To do to Done, and let agents and Mnemo move them too. Boards made in Obsidian Kanban show up here as well.": "Ang board ay isang note na may mga lane ng card: i-drag ang mga card mula To do papuntang Done, at puwede ring ilipat ng mga agent at ni Mnemo. Lumalabas din dito ang mga board na ginawa sa Obsidian Kanban.",
  "A board shows which notes it is in, and in Mnemo's replies a note that holds boards says so. Both stay folded until you open them.": "Ipinapakita ng board kung aling mga note ang kinalalagyan nito, at sa mga sagot ni Mnemo, sinasabi rin ito ng note na may mga board. Pareho silang nakatiklop hanggang buksan mo.",
  "A board you mention, Mnemo links or an agent changes shows under the reply as a live preview of its progress and first cards; a tap opens the board.": "Lumalabas sa ilalim ng sagot ang board na binanggit mo, na-link ng Mnemo o binago ng isang agent bilang live na preview ng progreso nito at mga unang card; isang tap lang at bubukas ang board.",
  "A browser left unused this long must sign in again. Connected agents are not affected.": "Kailangang mag-sign in ulit ang browser na matagal nang hindi nagagamit. Hindi apektado ang mga nakakonektang agent.",
  "A browser notification when a card on a board falls due, and once a day when cards are overdue, while Memora is open or installed. Off by default; the browser asks for permission when you turn it on. Kept in this browser.": "Isang browser notification kapag due na ang isang card sa board, at isang beses sa isang araw kapag may mga overdue na card, habang bukas o naka-install ang Memora. Naka-off bilang default; hihingi ng pahintulot ang browser kapag in-on mo ito. Nakatago sa browser na ito.",
  "A browser or an AI app. These rules are checked before the sign-in page.": "Isang browser o AI app. Sinusuri ang mga panuntunang ito bago ang sign-in page.",
