  "A change rewrites only the lines it touches, so the board opens the same in Obsidian. Its Markdown is in the ⋯ menu, and Turn into board makes a list note a board.": "Muling isinusulat ng bawat pagbabago ang mga linyang tinatamaan lang nito, kaya pareho pa rin ang pagbukas ng board sa Obsidian. Nasa ⋯ menu ang Markdown nito, at ginagawang board ng Gawing board ang isang list note.",
  "A chat about your whole vault": "Isang chat tungkol sa buong vault mo",
