  "Ask Mnemo what is overdue across your boards; it can tick cards off or move them for you, and agents get the same over MCP.": "Tanungin si Mnemo kung ano ang overdue sa lahat ng board mo; kaya nitong i-tick o ilipat ang mga card para sa iyo, at ganoon din ang agents sa pamamagitan ng MCP.",
  "Ask about the folder {name}, or anything in your vault.": "Magtanong tungkol sa folder na {name}, o anumang nasa vault mo.",
