  "Ask first: {mnemo} reads freely but asks before it changes notes or runs sub-agents. Auto: changes and sub-agents go ahead without asking. Read only: it reads and answers, and never changes notes. Saved at once.": "Magtanong muna: malayang nagbabasa si {mnemo} pero nagtatanong bago magbago ng note o magpatakbo ng sub-agent. Auto: tuloy ang mga pagbabago at sub-agent nang hindi nagtatanong. Read only: nagbabasa at sumasagot lang, at hindi nagbabago ng note. Agad na nase-save.",
  "Ask privately… nothing here is kept": "Magtanong nang pribado… walang itinatago rito",
  "Ask {mnemo}": "Tanungin si {mnemo}",
