  "Board actions": "Mga aksyon sa board",
  "Board and note menus offer only what belongs there, the lane menu is grouped with a colour row, and Embed in a note searches as you type.": "Ang mga menu ng board at note ay may laman lang na nauukol doon, naka-grupo ang lane menu na may hanay ng kulay, at ang I-embed sa isang note ay naghahanap habang nagta-type ka.",
  "Board color and icon": "Kulay at icon ng board",
  "Board colours and card ids that Memora keeps in the file are checked to survive a save in Obsidian Kanban.": "Sinuri na ang mga kulay ng board at card id na iniimbak ng Memora sa file para manatili ang mga ito pagkatapos mag-save sa Obsidian Kanban.",
