  "Browsers signed in to your account. Tap ⋯ to name a device, see its sign-ins or sign it out. Connected agents are not listed here and keep working.": "Mga browser na naka-sign in sa account mo. I-tap ang ⋯ para pangalanan ang device, tingnan ang mga sign-in nito o i-sign out ito. Hindi nakalista rito ang mga nakakonektang agent at patuloy silang gumagana.",
