  "Bulleted list": "Bulleted list",
  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "Walang nangyayari sa button? Piliin ang <b>Copy setup instead</b> at i-paste ito sa <code>~/.cursor/mcp.json</code> (gawin ang file kung wala pa).",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Walang nangyayari sa button? Piliin ang <b>Copy setup instead</b>, patakbuhin ang <b>MCP: Open User Configuration</b> mula sa Command Palette at i-paste doon. <code>servers</code> ang gamit ng VS Code, hindi <code>mcpServers</code>.",
