  "Chat width": "Lapad ng chat",
  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Makipag-chat sa model na pipiliin mo; nagbabasa, nagsusulat, nagta-tag, nagli-link, naglilipat at nag-aayos ng mga note si {mnemo} gamit ang sariling mga tool ng Memora. Hindi ito makakapag-browse sa web, makakapagpatakbo ng command, makakapagbura nang permanente o makakapagbago ng server. Naka-seal ang mga key sa server na ito at hindi kailanman ipinapadala sa browser.",
  "Chat with your notes agent": "Makipag-chat sa notes agent mo",
