  "Choose between 0.1 and 50 MB": "Pumili sa pagitan ng 0.1 at 50 MB",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "Pumili mula sa maraming wika sa Settings, Hitsura, bawat device. Sinusunod ng Auto ang browser mo.",
  "Choose your vault folder": "Piliin ang vault folder mo",
