  "Claude Desktop (older)": "Claude Desktop (luma)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Nagsa-sign in ang Claude at ChatGPT gamit ang Memora account mo. Walang kokopyahin.",
  "Claude models": "Mga Claude model",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Nagsa-sign in ang Claude sa OAuth, kaya walang ipapaste na key: magkakaroon ito ng sariling key kapag pinindot mo ang Allow. Kung walang sign-in, ikonekta ito bilang <b>Other app</b> at ipadala ang header na <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor at iba pa",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor at iba pa, bawat isa may sariling key",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "May kanya-kanyang access ang Claude, ChatGPT, Cursor, Codex at iba pa, kaya makikita mo kung ano ang ginagawa ng bawat isa.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Nagsasama sa iisang Memora ang Claude, Cursor, ChatGPT at sarili mong agent, maaabot mula sa computer na ito, local network o internet",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Binabasa ng Claude, Cursor, ChatGPT at ng sarili mong mga script ang mga note mo at nagdaragdag sila rito.",
