  "Click a card or tab to it first.": "Mag-click muna sa isang card o mag-Tab papunta rito.",
  "Click or tick tags to see their notes. Need more, like {example}? Use {button}": "Mag-click o mag-tick ng mga tag para makita ang mga note nila. Kailangan pa ng iba, tulad ng {example}? Gamitin ang {button}",
