  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Ang bawat AI app na ikokonekta mo ay isang agent na may sariling key, kaya makikita mo ang ginagawa ng bawat isa at puwede mong i-off ang isa nang hindi ginagalaw ang iba.",
