  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Isang app lang ang kinabibilangan ng bawat agent. Para gamitin ang Memora sa ibang app, gumawa ng hiwalay na agent para doon.",
  "Each app gets its own key": "May sariling key ang bawat app",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Bawat isa ay may maikling ID na hindi nagbabago, kaya malayang mapapalitan ang pangalan. Inihahanda sila ni Mnemo, binabago ang tagubilin o model nila, minemensahe, hinihintay, pinahihinto, tinatapos at inaalis, isa-isa o sabay-sabay, at kaya silang pagtrabahuhin sa background. Bawat card ay nagpapakita ng Tagubilin, Aktibidad at Sagot.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Sinusukat ang bawat uri sa sarili nitong espasyo: ang limitasyon nito kung meron, kung hindi ay ang gamit nito dagdag ang libreng espasyo sa disk{disk}. Walang laman na limitasyon: wala.",
  "Each one gets its own key from Memora.": "Bawat isa ay nakakakuha ng sariling key mula sa Memora.",
