  "Embed in a note…": "I-embed sa isang note…",
  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "Mag-embed ng bago o dating board sa isang note at gawin ang bawat isa doon mismo, o ilagay ang board sa kahit anong note mula sa ⋯ menu nito; ang simpleng link ay lumalabas bilang maliit na card.",
  "Emoji icon": "Emoji icon",
