  "Enter a username.": "Maglagay ng username.",
  "Enter an address or a web address first.": "Maglagay muna ng address o web address.",
  "Enter an address or a web address, then test.": "Maglagay ng address o web address, saka mag-test.",
  "Enter the code here": "Ilagay dito ang code",
  "Enter the folder path.": "Ilagay ang path ng folder.",
  "Enter the reset code": "Ilagay ang reset code",
  "Enter the setup code": "Ilagay ang setup code",
  "Enter your Memora password": "Ilagay ang password mo sa Memora",
  "Enter your current password.": "Ilagay ang kasalukuyang password mo.",
  "Enter your password": "Ilagay ang password mo",
  "Entries": "Mga entry",
  "Error": "Error",
  "Error 404": "Error 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Kahit araw-araw na gamit, mag-sa-sign in ulit ang browser pagkatapos ng haba ng oras na ito. Hindi ito puwedeng mas maikli kaysa sa oras ng inactivity.",
  "Every AI loses {n} tool at once. Asks first.": "Mawawalan ng {n} tool ang bawat AI nang sabay-sabay. Magtatanong muna.",
  "Every AI loses {n} tools at once. Asks first.": "Mawawalan ng {n} tool ang bawat AI nang sabay-sabay. Magtatanong muna.",
  "Every Kanban board in your notes": "Lahat ng Kanban board sa mga note mo",
  "Every action, newest first": "Bawat aksyon, pinakabago muna",
  "Every action, newest first, with search and filters.": "Bawat aksyon, pinakabago muna, may paghahanap at mga filter.",
  "Every address from one to another.": "Bawat address mula sa isa hanggang sa isa pa.",
  "Every address from the first to the last, joined by a dash.": "Bawat address mula sa una hanggang sa huli, pinag-ugnay ng gitling.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Karaniwang nagsisimula sa zero ang bawat agent. {bold} ikonekta ang bawat agent nang isang beses at pare-pareho silang magbabasa at magsusulat sa iisang vault, kaya magagamit ng iba ang natutunan ng isa.",
  "Every archived card is back on the board": "Nasa board na ulit ang bawat naka-archive na card",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Bawat board kasama ang mga lane at progreso nito. Nasaan man ang Bagong note, naroon din ang Bagong board: ang sidebar, Overview, mga folder, mga menu, paghahanap at ang B key.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Madi-disconnect ang bawat browser at agent hanggang simulan ulit ng kahit sino ang Memora sa makinang iyon. Hindi na ito masisimulan ulit ng page na ito.",
  "Every call shows up live in the brain and Activity": "Live na lumalabas sa brain at Activity ang bawat tawag",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Lumalabas sa Activity ang bawat pagbabagong ginagawa ni Mnemo at puwedeng i-undo mula sa History.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Lumalabas sa Activity ang bawat pagbabago, mula sa iyo o sa isang app, at puwedeng i-undo mula sa History.",
  "Every chat is archived.": "Naka-archive ang bawat chat.",
  "Every chat with your notes agent": "Bawat chat sa notes agent mo",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Mawawalan ang bawat nakakonektang AI ng lahat ng {n} tool nang sabay-sabay at hindi na makakabasa o makakapagbago ng mga note mo hanggang i-on mo ulit ang mga tool dito.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Mawawala ito sa bawat nakakonektang AI nang sabay-sabay. Puwede mo itong i-on ulit anumang oras.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Mawawala ang mga ito sa bawat nakakonektang AI nang sabay-sabay. Puwede mo silang i-on ulit anumang oras.",
  "Every connected agent loses its memory until Memora runs again.": "Mawawala ang memorya ng bawat nakakonektang agent hanggang tumakbo ulit ang Memora.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Bawat device sa home o office network, nakasulat bilang address/laki: ang 192.168.1.0/24 ay sakop ang 192.168.1.0 hanggang 192.168.1.255.",
  "Every device on a home or office network.": "Bawat device sa home o office network.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Bawat larawan sa folder ng mga note at kung saan ito ipinapakita, at ang mga larawang itinatago para sa mga chat ng Mnemo.",
  "Every image is used in a note.": "Ginagamit sa isang note ang bawat larawan.",
  "Every note": "Bawat note",
  "Every note and link, in 3D, as a graph or on a board.": "Bawat note at link, sa 3D, bilang graph o sa board.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Lilipat ang bawat note at subfolder sa \"{path}\" papunta sa {folder}; aalisin pagkatapos ang \"{name}\". Kung may kapareho nang pangalan doon, dadagdagan ito ng numero.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Nagiging card dito ang bawat note, sa loob ng frame ng folder nito. Ipinapakita ng gabay kung paano ipa-save sa AI ang kaalaman nito rito, o magsulat ka mismo ng note.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Nagiging tuldok ng liwanag dito ang bawat note, naka-grupo ayon sa folder. Ipinapakita ng gabay kung paano ipa-save sa AI ang kaalaman nito rito, o magsulat ka mismo ng note.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Ang bawat note na may tag na #{tag} ({notes}) ay makakakuha ng bagong pangalan, pati ang inline #tag sa teksto.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Ang bawat note na may tag na {tags} ay magkakaroon ng isang tag na lang ({notes}). Magbabago rin ang inline #tag sa teksto. Walang one-step na undo; may sariling history ang bawat note.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Live na lumalabas ang bawat basa at sulat ng agent, kaya lagi mong alam kung sino ang gumawa ng ano.",
  "Every request that reaches this rule is {verb}.": "Ang bawat request na umabot sa panuntunang ito ay {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Bawat request. Ilagay ito sa dulo para saluhin ang hindi nasakop ng mga panuntunan sa itaas.",
  "Every setting and where it lives.": "Bawat setting at kung saan ito matatagpuan.",
  "Every shortcut in the web UI.": "Bawat shortcut sa web UI.",
  "Every tag and its notes": "Bawat tag at ang mga note nito",
  "Every tool agents can call": "Bawat tool na puwedeng tawagin ng mga agent",
