  "Folder names floating over the part of the brain that holds their notes.": "Mga pangalan ng folder na lumulutang sa bahagi ng brain na may hawak ng mga note nila.",
  "Folder names: the point of each folder and the title over the area its notes fill.": "Mga pangalan ng folder: ang tuldok ng bawat folder at ang pamagat sa lugar na pinupunan ng mga note nito.",
