  "From anywhere": "Mula saanman",
  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "Mula ngayon, tuwing may sasabihin akong mahalaga, i-save mo sa Memora. Subukan mo ngayon: mag-save ng note na nagsimula akong gumamit ng Memora ngayon.",
