  "Gateway": "Gateway",
  "Gathered to-dos": "Mga nakolektang to-do",
  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Kinokolekta ang tunay na activity para sa {range}. Maaaring tumagal nang kaunti sa malaking log, mangyaring maghintay.",
  "General": "Pangkalahatan",
  "Get a one-time code on the server": "Kumuha ng isang beses na code sa server",
  "Get started": "Magsimula",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Kilalanin mo ako mula sa mga note ko. Silipin ang vault ko (mga bagong note, journal, proyekto, anumang tungkol sa akin) at itago ang natutunan mo gamit ang remember_owner: sino ako, ano ang pinagkakaabalahan ko, paano ko gustong sumagot, ano ang gusto ko. Maiikli at pangmatagalang bagay lang, huwag kailanman mga sikreto. Pagkatapos, sabihin sa akin sa ilang linya kung ano ang itinago mo.",
  "Gets its own agent key: read and write nodes over MCP": "May sariling agent key: magbasa at magsulat ng mga node sa MCP",
  "Getting started": "Pagsisimula",
  "GitHub answered HTTP {code}": "Sumagot ang GitHub ng HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Bigyan ang Claude, Cursor o anumang MCP app ng sariling key, saka hayaang i-save nito ang alam na nito tungkol sa iyo.",
  "Give a key read-only access, or let it write too.": "Bigyan ang key ng read-only na access, o hayaan din itong magsulat.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Bigyan ang bawat app o device ng sarili nitong agent. Sa Activity makikita kung sino ang gumawa ng ano, at puwede mong i-off ang isa nang hindi ginagalaw ang iba.",
  "Give it a name you recognise": "Bigyan ito ng pangalang makikilala mo",
  "Give the agent a name": "Bigyan ng pangalan ang agent",
  "Give the provider a name": "Bigyan ng pangalan ang provider",
  "Give the tag a name: letters, digits and - _ / . only.": "Bigyan ng pangalan ang tag: letra, digit at - _ / . lang.",
