  "How Memora looks for you. Saved in this browser only.": "Kung paano mukhang Memora para sa iyo. Sa browser na ito lang naka-save.",
  "How far apart the folder islands of the Clusters layout are.": "Gaano kalayo ang pagitan ng mga isla ng folder sa Clusters layout.",
  "How far apart the rings of the Radial layout are.": "Gaano kalayo ang pagitan ng mga singsing ng Radial layout.",
  "How full notes, images and chats are, and their limits": "Gaano na kapuno ang mga note, larawan at chat, at ang mga limitasyon nila",
