  "How much history the server keeps": "Gaano karaming history ang itinatago ng server",
  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Gaano kalaking espasyo ang kinukuha ng mga note, larawan at chat ng Mnemo, bawat isa laban sa sarili nitong espasyo. May banner na magbababala kapag halos puno na ang isa.",
  "How the agent itself shows up: its display name and colour.": "Paano lumalabas ang agent mismo: ang display name at kulay nito.",
  "How to update": "Paano mag-update",
  "How {mnemo} works": "Paano gumagana si {mnemo}",
  "Humanist": "Humanist",
  "Hyphenate long words": "I-hyphenate ang mahahabang salita",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Naghahanap, nagbabasa, nagsusulat, nagta-tag, nagli-link at nag-aayos ako ng mga note mo. Walang web, walang shell: vault mo lang.",
  "Icon": "Icon",
  "Icon {name}": "Icon na {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "Lumalago ang mga ideya kapag nagkakaugnay. I-link ang note na ito sa {a} o basahin ang {b}.",
  "Identity": "Identity",
  "Idle": "Idle",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Kung nakatulong ito sa iyo, makakatulong ang star sa GitHub o pagsabi sa kaibigan para mahanap ito ng iba. Ayos lang kung hindi.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Kung aalis ka, itatago ang mga ito sa device na ito at iaalok ulit kapag binuksan mo ang note.",
  "Image": "Larawan",
  "Image (or paste or drop one)": "Larawan (o i-paste o i-drop)",
  "Image deleted": "Nabura ang larawan",
  "Image line copied": "Nakopya ang linya ng larawan",
  "Image you attached": "Larawang in-attach mo",
  "Image {name}": "Larawang {name}",
  "Images": "Mga larawan",
  "Images can now be up to {n} MB": "Hanggang {n} MB na ang puwedeng larawan",
  "Images in this folder": "Mga larawan sa folder na ito",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Nakatabi ang mga larawan sa mga note na nagpapakita sa kanila. Piliin kung gaano kalaki ang puwede, at tingnan kung ano ang kinukuha ng mga note at larawan.",
  "Import and export": "Import at export",
  "Imported": "Na-import",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Sa ChatGPT, buksan ang <b>Settings → Apps &amp; Connectors → Advanced settings</b> at i-on ang <b>Developer mode</b>. Saka piliin ang <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Sa Claude (web o desktop), buksan ang <b>Settings → Connectors</b> at piliin ang <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Sa Claude Desktop, buksan ang <b>Settings → Developer → Edit Config</b>. Sa mas bagong bersyon, piliin ang <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Sa Windsurf, buksan ang <b>Settings → Cascade → MCP servers</b> at piliin ang <b>View raw config</b>.",
