  "Interface": "Interface",
  "Internet (tunnel)": "Internet (tunnel)",
  "Internet address (IP)": "Internet address (IP)",
  "It becomes your first rule.": "Ito ang magiging unang panuntunan mo.",
  "It becomes {path}. Links to its notes keep working.": "Magiging {path} ito. Patuloy na gagana ang mga link sa mga note nito.",
  "It can change notes, but nothing lets it connect.": "Puwede itong magbago ng mga note, pero walang paraan para makakonekta ito.",
  "It can search and read your notes, but not change them": "Makakahanap at makakabasa ito ng mga note mo, pero hindi makakapagbago",
  "It can search, read and save your notes": "Makakahanap, makakabasa at makakapag-save ito ng mga note mo",
  "It can {list}.": "Puwede itong {list}.",
  "It cannot do anything yet": "Wala pa itong magagawa",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "May buong kontrol ito: nagbabasa at nagbabago ng mga note, at puwedeng mamahala ng Memora at ng ibang agent",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "May {n} note ito. Susunod, pipiliin mo kung ano ang mangyayari sa mga ito: ilipat sa ibang folder, o ilipat sa Trash. Wala pang nababago.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "May {n} note ito. Susunod, pipiliin mo kung ano ang mangyayari sa mga ito: ilipat sa ibang folder, o ilipat sa Trash. Wala pang nababago.",
  "It is added at the end, as rule {n}, so it is checked last.": "Idinadagdag ito sa dulo, bilang panuntunan {n}, kaya huli itong susuriin.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Mawawala ito pag-alis mo, kasama ang mga larawan. Makikita pa rin sa Activity at History ang mga pagbabago sa notes mo.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Naka-lock ito sa server. Ilagay ang password mo sa Memora at ilalagay ito para sa iyo ng mga button sa ibaba.",
  "It is taking a while. Check the server, then reload this page.": "Natatagalan ito. Suriin ang server, saka i-reload ang page na ito.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Sa Pinned list lang ito aalis; mananatili sa lugar nito ang folder mismo.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Sa Pinned list lang ito aalis; mananatili sa lugar nito ang note mismo.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Maaaring napalitan ng pangalan, nailipat o nabura ito. Naghihintay sa Trash ang mga nabura na note.",
  "It moves; links to it are updated and pins follow.": "Lumilipat ito; ina-update ang mga link dito at sumusunod ang mga pin.",
  "It must sign in again and is told why": "Kailangan itong mag-sign in ulit at sasabihin kung bakit",
  "It prints a one-time code. This page moves on by itself.": "Nagpi-print ito ng isang beses na code. Kusang magpapatuloy ang page na ito.",
  "It reached Memora but did not finish. It often works on the next try.": "Naabot nito ang Memora pero hindi natapos. Madalas gumagana sa susunod na subok.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Naabot nito ang Memora pero hindi natapos: {error} Madalas gumagana sa susunod na subok.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Lumalabas ito sa ilalim ng pangalang ito sa Activity, brain at graph. Pangalanan ito ayon sa device kapag ginagamit mo ang {app} sa higit sa isang lugar, tulad ng \"{example}\".",
  "It was shown when it was made. Make a new key to see one again.": "Ipinakita ito noong ginawa. Gumawa ng bagong key para makita ulit ang isa.",
  "Italic": "Italic",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "Aalisin ang API key at mga model nito. Mananatili ang mga chat; ang chat na gumamit ng isa sa mga model nito ay lilipat sa default.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Pareho ang key at access nito sa bawat notes folder. Magkonekta ng isa pa anumang oras.",
  "Its key is filled in on the next step": "Pupunuin ang key nito sa susunod na hakbang",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Tinatanggihan ang key nito hanggang i-on mo ulit. Walang buburahin.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Tinatanggihan ang key nito. I-on ito para makakonekta ulit gamit ang parehong key.",
  "Its key stopped working. You can restore it until you reload the app.": "Tumigil sa paggana ang key nito. Maibabalik mo ito hanggang mag-reload ka ng app.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Agad na titigil sa paggana ang key nito. Mananatili ang nakaraang activity; maibabalik mo ito hanggang mag-reload ka ng app.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Isang beses lang ipinakita ang key nito, noong ginawa. Papalitan ito ng bagong key at agad titigil sa paggana ang luma.",
  "Its notes are in its folders. You can also start one here.": "Nasa mga folder nito ang mga note nito. Puwede ka ring magsimula ng isa rito.",
  "Its numbers, timeline and export.": "Ang mga numero, timeline at export nito.",
  "Its old folder is not known, so it goes to the top level": "Hindi alam ang dating folder nito, kaya mapupunta ito sa pinakataas na antas",
  "Its page": "Pahina nito",
  "Its page shows how to connect it.": "Ipinapakita ng pahina nito kung paano ito ikonekta.",
  "Its page: status, recent calls, access and settings.": "Pahina nito: status, mga kamakailang tawag, access at settings.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Custom na halo ang mga pahintulot nito. Pumili ng antas para palitan ang mga ito, o i-fine-tune sa Advanced.",
  "Its {n} card goes to the Archive first, where you can restore it to another lane.": "Ang {n} card nito ay mapupunta muna sa Archive, kung saan mo ito maibabalik sa ibang lane.",
  "Its {n} cards go to the Archive first, where you can restore them to another lane.": "Ang {n} card nito ay mapupunta muna sa Archive, kung saan mo ito maibabalik sa ibang lane.",
