  "Lanes fade at the edge while there is more to see, snap one at a time on phones with dots to jump between them, and links, tags and mentions on cards show as chips.": "Lumalabo ang mga lane sa gilid habang may makikita pa, isa-isang pumupuwesto sa phone na may mga tuldok para lumipat sa pagitan nila, at lumalabas bilang chips ang mga link, tag at mention sa mga card.",
