  "Lets the app use Memora's tools (MCP), limited by the tool list below. Every AI app needs this.": "Pinapagamit sa app ang mga tool ng Memora (MCP), na nililimitahan ng listahan ng tool sa ibaba. Kailangan ito ng bawat AI app.",
