  "Locks, mentions and assignments so agents do not overwrite each other.": "Mga lock, mention at assignment para hindi mag-overwrite ang mga agent sa isa't isa.",
  "Long chats, light": "Mahahabang chat, magaan",
  "Long enough. A few more characters make it stronger.": "Sapat na ang haba. Mas titibay ito kung dadagdagan ng ilang character.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Lalabas bilang checklist sa itaas ng message box ang mas mahahabang gawain: hindi pa nasimulan, ginagawa, tapos na.",
  "Longest sign-in": "Pinakamahabang sign-in",
  "Longest sign-in must be at least the inactivity time": "Dapat hindi bababa sa oras ng inactivity ang pinakamahabang sign-in",
  "Look for tags that mean the same thing": "Maghanap ng mga tag na pareho ang ibig sabihin",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Tingnan ang project sa folder na ito at i-save sa Memora: para saan ito, paano ito binuo, paano patakbuhin, mga teknikal na desisyon, at anumang sulit tandaan. Gumawa ng isang note bawat paksa, sa folder na ipinangalan sa project sa loob ng Projects.",
