  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Gumawa ng agent para sa bawat app o device na ginagamit mo. May sariling key ang bawat isa, kaya makikita mo ang ginagawa nito at maio-off mo ito nang mag-isa.",
