  "Measuring…": "Sinusukat…",
  "Medium": "Katamtaman",
  "Medium text": "Katamtamang teksto",
  "Meet Mnemo, your notes agent": "Kilalanin si Mnemo, ang notes agent mo",
  "Memora address (MCP endpoint)": "Address ng Memora (MCP endpoint)",
  "Memora already uses this folder.": "Ginagamit na ng Memora ang folder na ito.",
  "Memora by Codrihub Tech": "Memora ng Codrihub Tech",
  "Memora can save notes here": "Makakapag-save ng mga note dito ang Memora",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Sinusuri ng Memora ang folder at hihingi ng kumpirmasyon bago lumipat. Walang ililipat o kokopyahin, at makakabalik ka rito. Gumagamit ng Docker? Gumamit ng folder na naka-mount sa container.",
  "Memora could not start.": "Hindi nakapagsimula ang Memora.",
  "Memora data folder": "Data folder ng Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Sinusuri muna ng Memora kung umiiral ang bagong folder (o magagawa) at kung makakapag-save ito ng mga note doon. Kung mabigo ang pagsusuri, walang magbabago.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Sinusuri muna ng Memora kung umiiral ang bagong folder at kung makakapag-save ito ng mga note doon. Kung mabigo ang pagsusuri, walang magbabago.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Ang Memora sa wika mo, si Mnemo na ipinapakita ang plano niya habang gumagawa, at ikaw ang pumipili kung ano ang magagamit at makikita nito.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Ang Memora ay notes app na magagamit din ng mga AI app mo. Isusulat mo rito, babasahin at susulatan nila ang parehong mga note, at lagi mong makikita kung ano ang nagbago.",
  "Memora is free and open source": "Libre at open source ang Memora",
  "Memora is free and open source. A star helps others find it.": "Libre at open source ang Memora. Nakakatulong ang star para mahanap ito ng iba.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Ang Memora ay memorya, pinahusay: ginawa para tandaan ang natututunan mo at ng AI mo, at mas maraming maaalala habang mas ginagamit mo.",
  "Memora is restarting": "Nagre-restart ang Memora",
  "Memora is shut down": "Naka-shut down ang Memora",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Walang laman pa rin ang Memora. Magkonekta ng AI app, magpadala ng isang prompt, at isi-save nito rito ang alam nito tungkol sa iyo, bilang mga note na mababasa, mae-edit at makikita mo sa brain.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Nagtatago ang Memora ng listahan ng mga tag mo para imungkahi habang nagta-type ka. I-refresh ito kung may nawawalang tag o luma na.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Itinatago ng Memora ang bawat bersyon ng note kapag git repository ang vault folder. Patakbuhin nang isang beses ang {cmd} sa vault folder (tingnan ang Configuration, “Version history” sa docs); mula noon, itatago rito ang bawat pagbabago.",
  "Memora keeps it in one place:": "Itinatago ito ng Memora sa isang lugar:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Sine-save ng Memora ang bawat note bilang plain Markdown file sa makinang pinapatakbuhan nito. Walang naka-lock: buksan ang mga file sa anumang editor, i-back up, o itago sa Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Nagsasalita ang Memora ng MCP sa streamable HTTP. Ipinapadala ng mga app ang key sa header na <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Humihinto ang Memora sa makinang pinapatakbuhan nito. Ligtas ang mga note mo sa disk.",
  "Memora version": "Bersyon ng Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Available na ang Memora v{latest}. Nagpapatakbo ng v{current} ang server na ito.",
  "Memora v{version} is available": "Available na ang Memora v{version}",
  "Memora, open Overview": "Memora, buksan ang Overview",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: isang notes vault na ikaw ang nagho-host, may agent na nag-aayos nito.",
  "Memory used: {used} of {win}": "Gamit na memorya: {used} sa {win}",
  "Mentioned in": "Binanggit sa",
  "Mentions": "Mga mention",
  "Menus that fit": "Mga menu na akma",
  "Menus that fit where you are, an archive you can search, softer progress and due dates, and steps you can tick on the card.": "Mga menu na akma sa kinaroroonan mo, archive na mahahanap, mas banayad na progress at due date, at mga hakbang na matitiktikan sa card.",
  "Menus, tidied": "Inayos na mga menu",
  "Merge": "I-merge",
  "Merge into": "I-merge sa",
