  "Message to {mnemo}": "Mensahe kay {mnemo}",
  "Messaged {agent}": "Minensahe si {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Eksaktong magkahanay ang mga mensahe at ang message box sa bawat lapad, may sariling surface ang pagpili ng model, kasya sa telepono ang fleeting chat, at hindi na gumagalaw ang mga opsyon ng tanong habang tina-tap mo.",
  "Middle-drag": "Middle-drag",
  "Midnight": "Hatinggabi",
  "Minimap": "Minimap",
  "Minimap: click or drag to move the view": "Minimap: i-click o i-drag para ilipat ang view",
  "Mist": "Mist",
  "Mnemo (AI agent)": "Mnemo (AI agent)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Kayang gawin ng Mnemo at ng mga agent sa isang board ang lahat ng kaya mo, sa pamamagitan ng MCP, sa likod ng apat na Kanban permission switch na sumusunod sa Magtanong muna, Auto at Read only.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Nakatago ang button ng Mnemo. Ipakita ulit mula sa More, Show the Mnemo button.",
  "Mnemo goes on without sub-agents": "Magpapatuloy si Mnemo nang walang sub-agent",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Wala pang model si Mnemo: magdagdag ng provider at mga model nito sa Settings, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Built in sa Memora si Mnemo. Ikonekta ang sarili mong AI key, saka magtanong sa simpleng salita: naghahanap, nagsusulat, nagta-tag, nagli-link at nag-aayos ito ng mga note para sa iyo.",
  "Mnemo is still answering in this chat": "Sumasagot pa si Mnemo sa chat na ito",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Ang Mnemo ay ang agent na built-in sa Memora. Ikonekta ang sarili mong AI key at magtanong sa simpleng salita: inaayos nito ang mga note mo habang ginagamit ito ng iba mong app.",
  "Mnemo keeps at most {n} providers; delete one first": "Hanggang {n} provider lang ang itinatago ni Mnemo; magbura muna ng isa",
  "Mnemo knows what is due": "Alam ni Mnemo kung ano ang due",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Pinamamahalaan ni Mnemo ang mga sub-agent nito, itinatabi ang plano kasama ng chat, at mas bagay ang chat sa bawat screen.",
  "Mnemo runs its sub-agents": "Pinapatakbo ni Mnemo ang mga sub-agent nito",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Huminto si Mnemo pagkatapos ng {n} hakbang; sabihin ang \"continue\" para magpatuloy.",
  "Mnemo's plan, live": "Plano ni Mnemo, live",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "May sariling banda ang tanong ni Mnemo, at nasa ibaba ang mga sagot bilang mga hanay na tina-tap, gaano man karami ang kailangan ng tanong.",
  "Mnemo, your notes agent": "Mnemo, ang notes agent mo",
