  "More: rename, move, colour, delete": "Higit pa: palitan ang pangalan, ilipat, kulay, burahin",
  "More: rename, move, pin, delete": "Higit pa: palitan ang pangalan, ilipat, i-pin, burahin",
  "Most AI apps start each chat from nothing, and each keeps its own memory. With Memora, Claude, Cursor and any other app that speaks MCP read and write the same notes, so what one app learns, the others can use.": "Karamihan sa mga AI app ay nagsisimula ng bawat chat sa wala, at may sariling memorya ang bawat isa. Sa Memora, nagbabasa at nagsusulat ang Claude, Cursor at anumang app na nagsasalita ng MCP sa parehong mga note, kaya magagamit ng iba ang natutunan ng isang app.",
