  "Not created yet. Click to create it.": "Hindi pa nagagawa. I-click para gawin.",
  "Not done": "Hindi pa tapos",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Hindi nagawa: nasa Ask first mode si Mnemo, kaya naghihintay ng OK ng owner ang mga pagbabago. Magtanong gamit ang ask_owner (sabihin kung ano ang babaguhin mo; magbigay ng opsyon na may approve: true tulad ng \"Yes, go ahead\"), saka gawin ang pagbabago pagkatapos nilang aprubahan.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Hindi nagawa: nasa Read only mode si Mnemo, kaya hindi binabago ang mga note. Sabihin kung ano ang babaguhin mo; puwedeng lumipat ang owner sa Ask first o Auto sa chat.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Hindi nagawa: nasa Ask first mode ang chat, kaya hindi makakapagbago ng note ang sub-agent. Sabihin sa sagot mo kung ano ang dapat magbago; magtatanong si Mnemo sa owner.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Hindi nagawa: in-off ng owner ang {tool} para kay Mnemo (Settings, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Hindi nagawa: in-off ng owner ang {tool} para sa mga sub-agent (Settings, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Hindi natapos: pinutol ng owner ang sagot na ito bago bumalik ang tool.",
