  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Hindi nasimulan: ang \"{name}\" ay tumutugma sa higit sa isang model o wala nang eksakto. Mga malapit: {list}. Tanungin ang owner kung alin, o ibigay ang eksaktong id.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Hindi nasimulan: walang model na \"{name}\" dito. Sabihin sa owner, o iwanan ang model para gamitin ang default model nila.",
