  "Notes": "Mga note",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Iisang page frame ang gamit ng mga note at board, na may parehong spacing sa phone, tablet at desktop, at iisang maayos na itsura ang mga link sa ibaba ng note na puwedeng i-fold.",
  "Notes and boards, connected": "Mga note at board, magkakonekta",
  "Notes and images in the notes folder.": "Mga note at larawan sa notes folder.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Lumalabas dito bilang mapa ang mga note at ang mga link sa pagitan nila. Ipinapakita ng gabay kung paano ipa-save sa AI ang kaalaman nito rito, o magsulat ka mismo ng note.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Lumalabas ang mga note habang sine-save ng AI at pinapailaw ang brain. Magiging dashboard mo ang page na ito pagdating ng unang note.",
  "Notes are not a password manager.": "Hindi password manager ang mga note.",
  "Notes changed in the app or in the folder": "Mga note na nabago sa app o sa folder",
  "Notes folder": "Notes folder",
  "Notes folder switched": "Napalitan ang notes folder",
  "Notes from {name}": "Mga note mula kay {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Bumubukas bilang board ang mga note na nasa Obsidian Kanban format. I-drag ang mga card at lane gamit ang mouse o daliri, at napupunta sa history ng note ang bawat pagbabago.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Hindi ililipat, kokopyahin o buburahin ang mga note sa kasalukuyang folder. Makakabalik ka rito anumang oras.",
  "Notes inside a folder": "Mga note sa loob ng folder",
  "Notes it found": "Mga note na nahanap nito",
