  "Notes that carry at least one tag": "Mga note na may kahit isang tag",
  "Notes that carry every tag": "Mga note na may bawat tag",
  "Notes that link nowhere and are linked from nowhere.": "Mga note na walang pinupuntahang link at walang nagli-link.",
  "Notes touched": "Mga ginalaw na note",
  "Notes with a tag; the start of the tag is enough": "Mga note na may tag; sapat na ang simula ng tag",
  "Notes you delete wait here, so you can bring them back.": "Naghihintay dito ang mga note na binura mo, para maibalik mo.",
  "Notes you or your AIs write show up here, newest first.": "Lalabas dito ang mga note na isinulat mo o ng mga AI mo, pinakabago muna.",
  "Notes, folders and images in this chat": "Mga note, folder at larawan sa chat na ito",
