  "Nothing here": "Walang laman dito",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Wala pang nakatago: lagyan ng tsek ang mga agent na pagtataguan nito. Sa ngayon, nakikita ito ng lahat ng {n} agent.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Wala pang nakatago: lagyan ng tsek ang mga agent na pagtataguan nito. Sa ngayon, nakikita ito ng nag-iisang agent.",
  "Nothing in 24h": "Wala sa 24h",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Walang tugma sa mga pangalan ng note, folder o teksto, at walang kahawig na baybay. Subukan ang mas kaunting letra, ibang baybay, o salita mula sa loob ng note.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Walang laman sa nakaraang 24 oras. Lalabas dito ang ginagawa ng mga AI mo habang nangyayari.",
