  "Nothing is allowed. Turn something on, or pause the agent instead.": "Walang pinapayagan. Mag-on ng isa, o i-pause na lang ang agent.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Walang nawawala: mananatili sa history ang kasalukuyang teksto bilang v{n}, kaya makakabalik ka anumang oras.",
