  "Offline": "Offline",
  "Offline · Memora": "Offline · Memora",
  "Offline, retrying": "Offline, sinusubukan ulit",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Lumang Gemini CLI na walang <code>gemini mcp add</code>: idagdag ang server sa <code>~/.gemini/settings.json</code> sa ilalim ng <code>mcpServers</code>, gamit ang <code>httpUrl</code> at parehong header.",
  "Older changes stay in History.": "Nananatili sa History ang mas lumang pagbabago.",
  "Older messages were left out to fit the model's context.": "Inalis ang mas lumang mga mensahe para magkasya sa context ng model.",
  "Older than 30 days": "Mas luma sa 30 araw",
  "Older than 7 days": "Mas luma sa 7 araw",
  "Older than 90 days": "Mas luma sa 90 araw",
  "Older versions of a note: read, compare, restore, and the trash.": "Mga mas lumang bersyon ng note: basahin, ihambing, ibalik, at ang trash.",
  "Oldest entry": "Pinakamatandang entry",
  "On": "On",
  "On a board": "Sa isang board",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Sa desktop, hilahin ang gilid ng listahan ng chat o ng side panel para palaparin o paliitin ito. May minimum na lapad ang bawat isa at natatandaan ang lapad nito.",
  "On hover": "Kapag naka-hover",
  "On its avatar, its sparks in the brain and every activity row.": "Sa avatar nito, sa mga spark nito sa brain at sa bawat row ng activity.",
  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "Sa pahina ng Mga board, may ⋯ menu ang bawat board para buksan, palitan ang pangalan, ilipat, i-duplicate, kulayan, o ilipat sa trash. Bubukas din ito sa right-click o matagal na pindot.",
  "On this page": "Sa pahinang ito",
  "On: tap to switch off": "On: i-tap para i-off",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "On: itinatala ni {mnemo} ang nakukuha nito sa mga chat. Off: ang idinagdag mo lang dito. Agad na nase-save.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Kapag na-install na, may sariling icon ang app, bumubukas nang full screen at maaabot kahit mawala ang network.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Kapag nakakonekta na, i-paste ito sa bagong chat sa app na iyon. Sinasabi nito sa AI na i-store sa Memora ang alam nito.",
  "Once its app is set up, every call shows up here as it happens.": "Kapag na-set up na ang app nito, lalabas dito ang bawat tawag habang nangyayari.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Kapag nakakonekta na ang {name}, lalabas dito nang live ang lahat ng binabasa, isinusulat at hinahanap nito.",
  "One address": "Isang address",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Isang agent bawat app o device: sariling key, sariling pangalan sa Activity, naio-off nang mag-isa.",
  "One click": "Isang click",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Isang device o koneksyon, tulad ng 203.0.113.7. Hanapin ang \"what is my IP\" para makita ang sa iyo.",
  "One device or connection.": "Isang device o koneksyon.",
  "One folder of notes that you and every connected AI share.": "Isang folder ng mga note na ibinabahagi mo at ng bawat nakakonektang AI.",
  "One is hidden by the folder rule.": "Isa ang nakatago dahil sa panuntunan ng folder.",
  "One key per agent, its own permissions.": "Isang key bawat agent, sariling mga pahintulot.",
  "One last step": "Huling hakbang",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Isang memorya na binabasa at sinusulatan ng bawat agent, at makikita, mae-edit at maikokonekta mo ang lahat.",
  "One memory for every AI": "Isang memorya para sa bawat AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "May isang note na nagpapakita ng larawang ito; lalabas itong nawawala roon. Itinatago ito ng version history.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Isa bawat linya. Lalabas ang mga ito sa mga mungkahi sa bagong chat, may markang Yours, at mananatili hanggang baguhin mo.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Isang pribadong memorya na ibinabahagi mo at ng mga AI app mo, kaya hindi na kailangang magpaliwanag nang dalawang beses.",
  "One set of notes for every AI app": "Isang set ng mga note para sa bawat AI app",
  "One thin progress bar instead of stark lane bars, softer shadows, lane colours across the whole lane, and overdue shown as a stroke.": "Isang manipis na progress bar sa halip na matitigas na lane bar, mas banayad na anino, kulay ng lane sa buong lane, at overdue na ipinapakita bilang guhit.",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "PNG, JPEG, WebP at GIF lang ang puwedeng idagdag na larawan",
  "Only in the current version": "Sa kasalukuyang bersyon lang",
  "Only in version {n}": "Sa bersyon {n} lang",
  "Only letters, digits and - _ / . can be used.": "Letra, digit at - _ / . lang ang puwedeng gamitin.",
  "Only looks at notes; changes nothing.": "Tumitingin lang sa mga note; walang binabago.",
  "Only looks things up and never writes. For agents with a read-only key.": "Naghahanap lang at hindi nagsusulat. Para sa mga agent na may read-only na key.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Ang mga larawan lang sa pinakabago mong mensahe ang napupunta sa image model, at malalaman mo ito sa maikling toast.",
  "Only reads and answers; never changes notes": "Nagbabasa at sumasagot lang; hindi nagbabago ng note",
  "Only the agents you pick. New agents can’t see it.": "Mga agent lang na pipiliin mo. Hindi ito makikita ng mga bagong agent.",
  "Only the first rule that fits a request counts.": "Ang unang panuntunang tumutugma lang sa request ang binibilang.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Ang mga pinakabagong tanong lang ang unang lumalabas; dumarating ang mga luma kapag nag-scroll ka pataas o tumalon sa timeline.",
  "Only the ones I pick": "Ang pipiliin ko lang",
  "Only these agents": "Mga agent na ito lang",
