  "Only this note uses these settings.": "Ang note lang na ito ang gumagamit ng mga setting na ito.",
  "Only {names} can see this {what}. Every other agent, including ones added later, is blocked.": "{names} lang ang makakakita sa {what} na ito. Naka-block ang bawat ibang agent, kasama ang mga idadagdag pagkatapos.",
