  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Opsyonal. Ilang salita kung sino ka, ano ang pinagtatrabahuhan mo, paano mo gustong sumagot. Itinatago ito ni {mnemo} at mababago mo anumang oras sa Settings.",
