  "Password saved. Sign in with the new password.": "Na-save ang password. Mag-sign in gamit ang bagong password.",
  "Passwords are reset on the server that runs Memora.": "Nire-reset ang mga password sa server na nagpapatakbo ng Memora.",
  "Passwords do not match": "Hindi magkapareho ang mga password",
