  "Passwords match": "Magkapareho ang mga password",
  "Past activity keeps the old name; new activity uses this one.": "Mananatili ang lumang pangalan sa nakaraang activity; ito na ang gagamitin sa bagong activity.",
  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Ang lampas na sa due date ay may kulay-babala at ang ngayon ay mas mahinang kulay, at binibilang ng pahina ng Mga board ang overdue. Mas masusunod ang sariling kulay ng petsa ng board.",
  "Paste both into the app and save.": "I-paste ang pareho sa app at i-save.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "I-paste ito sa terminal at pindutin ang <kbd>Enter</kbd>, saka simulan ang Codex sa parehong terminal.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "I-paste ito sa terminal at pindutin ang <kbd>Enter</kbd>. Saka simulan ang Claude Code, o i-restart ito: kusang naglo-load ang Memora.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "I-paste ito sa terminal at pindutin ang <kbd>Enter</kbd>. Saka simulan ang Gemini CLI, o i-restart ito, at i-type ang <code>/mcp</code> para makita ang Memora.",
  "Paste it into the app where it asks for a key.": "I-paste ito sa app kung saan humihingi ng key.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "I-paste ito sa file at i-save, saka pindutin ang <b>Refresh</b>. Lalabas ang Memora sa listahan.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "I-paste ito sa file, i-save, at i-restart ang Claude Desktop. Kailangan nito ng Node.js sa computer na ito.",
  "Paste it into {app}": "I-paste sa {app}",
  "Paste the API key": "I-paste ang API key",
  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "I-paste ang mga ito nang isang beses kung saan binabasa ng {app} ang mga standing instruction nito, para magamit nito ang Memora sa bawat usapan, hindi lang kapag hiniling.",
