  "Save failed": "Nabigo ang pag-save",
  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "I-save sa Memora ang ibinahagi ko sa iyo tungkol sa personal kong buhay: ang mga interes, gawi, layunin, mga taong mahalaga sa akin at mga bagay na pinahahalagahan ko. Ilagay ang mga note na ito sa folder na pinangalanang Private, isang note bawat paksa, at i-link ang magkakaugnay na note. Huwag mag-save ng password, card number o iba pang sikreto. Kapag tapos ka na, sabihin kung ano ang na-save mo.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "I-save sa Memora ang alam mo tungkol sa trabaho ko: ang role ko, ang team ko, ang mga project ko at kung nasaan na ang mga ito, at ang mga desisyong ginawa natin. Gumawa ng isang note bawat project o paksa at i-link ang mga ito.",
