  "Tell {mnemo} how you like things, in your own words: the language to answer in, how to name notes, folders to leave alone…": "Sabihin kay {mnemo} kung paano mo gusto ang mga bagay, sa sarili mong salita: ang wikang gagamitin sa pagsagot, paano pangalanan ang mga note, mga folder na hindi dapat galawin…",
