  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "May long-term memory ka na ngayon sa pamamagitan ng Memora. I-save sa Memora ang lahat ng alam mo tungkol sa akin mula sa mga usapan natin: sino ako, ang trabaho ko, ang mga project ko, mga kagustuhan ko at mahahalagang desisyon. Gumawa ng isang note bawat paksa sa angkop na folder, at i-link ang mga note na magkakaugnay. Kapag tapos ka na, sabihin kung ano ang na-save mo.",
