  "Your connected AI works in this folder now. Ask one to save what it knows here, or write a note yourself. Switched folders by mistake? Switch back under Settings, Notes folder.": "Gumagana na sa folder na ito ang nakakonekta mong AI. Hilingin sa isa na i-save ang alam nito rito, o magsulat ka mismo ng note. Napalitan ang folder nang hindi sinasadya? Bumalik sa Settings, Notes folder.",
