  "{app} opens a Memora page in your browser to ask for permission. If you closed it, start again from step 1.": "Nagbubukas ang {app} ng pahina ng Memora sa browser mo para humingi ng pahintulot. Kung isinara mo ito, magsimula ulit sa hakbang 1.",
