  "{mnemo} activity": "Activity ni {mnemo}",
  "{mnemo} asks": "Nagtatanong si {mnemo}",
  "{mnemo} asks before sub-agents run": "Nagtatanong si {mnemo} bago tumakbo ang mga sub-agent",
  "{mnemo} asks this model when you want a picture made.": "Tinatanong ni {mnemo} ang model na ito kapag gusto mong gumawa ng larawan.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "Nakatago ang button ng {mnemo}. Ibalik mula sa More, Show the {mnemo} button.",
  "{mnemo} button hidden. Show it again here or from More.": "Nakatago ang button ng {mnemo}. Ipakita ulit dito o mula sa More.",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "Hindi nakasulat si {mnemo} ng mga bago ngayon. Suriin ang model sa Settings.",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "Ibinibigay ni {mnemo} ang mga larawan sa model na ito kapag hindi makakita ang chat model.",
  "{mnemo} is working on this": "Ginagawa ito ni {mnemo}",
  "{mnemo} keeps only what you add": "Itinatago lang ni {mnemo} ang idinagdag mo",
  "{mnemo} knows nothing about you yet.": "Wala pang alam si {mnemo} tungkol sa iyo.",
  "{mnemo} looks after your notes": "Inaalagaan ni {mnemo} ang mga note mo",
  "{mnemo} may learn about you": "Puwedeng matuto si {mnemo} tungkol sa iyo",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "Sa mga note mo lang gumagana si {mnemo}. Lumalabas sa Activity ang bawat pagbabago at puwedeng i-undo mula sa History.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "Binabasa ni {mnemo} ang vault mo sa bagong chat at itinatago rito ang natututunan nito.",
  "{mnemo} settings saved": "Na-save ang settings ni {mnemo}",
  "{mnemo} settings: models and keys": "Settings ni {mnemo}: mga model at key",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "Kusang nagsisimula ng mga sub-agent si {mnemo} kapag mahahati nang maayos ang gawain; walang kailangang i-set up. Tumatakbo ang mga ito sa default na model mo, saka sa mga fallback, maliban kung magpangalan ka ng model sa chat. Sundan sila, at palitan ang model nila, sa Agents sa kanang itaas ng chat. May sarili silang token, kaya sa Ask first nagtatanong si {mnemo} at sinasabi kung humigit-kumulang ilan; sa Auto tuloy lang sila. Agad na nase-save.",
  "{mnemo} stopped it": "Itinigil ito ni {mnemo}",
  "{mnemo} will keep that in mind": "Tatandaan iyon ni {mnemo}",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "Sumusulat si {mnemo} ng mga bagong mungkahi mula sa kamakailan mong mga note (mananatili ang sa iyo)",
  "{mnemo}'s own ({n})": "Sariling mga mungkahi ni {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Ang sariling mga tala ni {mnemo} kung paano makipag-usap sa iyo, binabasa sa bawat chat. Mag-click ng isa para baguhin.",
  "{mnemo}, your notes agent": "{mnemo}, ang notes agent mo",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "Hindi nakakakita ng larawan ang {model}; mga pangalan lang ang nakuha nito. Magtakda ng model na nagbabasa ng larawan sa Settings para makita ang mga ito.",
  "{model} cannot look at images; the image model described them for it.": "Hindi nakakakita ng larawan ang {model}; inilarawan ng image model ang mga ito para dito.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "Hindi nakakabasa ng larawan ang {model}, kaya mga pangalan lang ang nakukuha nito. Magtakda ng model na nagbabasa ng larawan, o palitan ang model ng chat na ito.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "Hindi nakakabasa ng larawan ang {model}, kaya mga pangalan lang ang nakuha nito. Magtakda ng model na nagbabasa ng larawan, o palitan ang model ng chat na ito.",
  "{model} cannot read pictures, so the image model looked at them for it.": "Hindi nakakabasa ng larawan ang {model}, kaya tiningnan ito ng image model para dito.",
  "{model} cannot read pictures, so the image model looks at them for it.": "Hindi nakakabasa ng larawan ang {model}, kaya tinitingnan ito ng image model para dito.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "Hindi sumagot ang {model} ({why}); susubukan ulit sa loob ng {wait} s ({n}/{total})…",
